// Copies the browser assets of pdf.js, zxing-wasm and tesseract.js into `public/vendor/`
// (gitignored, regenerated by `predev` and `prebuild`).
//
// Why: by default these libraries download their workers, wasm and language data from public
// CDNs (jsDelivr, tessdata.projectnaptha.com). Self-hosting means certificate processing makes
// no third-party requests, works behind a strict CSP (Phase 8), and is pinned to exactly the
// versions in package-lock.json.
import { cp, mkdir, readdir, rm } from 'node:fs/promises';
import path from 'node:path';

const root = path.resolve(import.meta.dirname, '..');
const nm = (...p) => path.join(root, 'node_modules', ...p);
const out = (...p) => path.join(root, 'public', 'vendor', ...p);

await rm(out(), { recursive: true, force: true });

// pdf.js: worker, wasm decoders (JBIG2 is used by NPTEL's 2026 PDFs for the QR image), fonts
await mkdir(out('pdfjs'), { recursive: true });
await cp(nm('pdfjs-dist', 'build', 'pdf.worker.min.mjs'), out('pdfjs', 'pdf.worker.min.mjs'));
await cp(nm('pdfjs-dist', 'wasm'), out('pdfjs', 'wasm'), { recursive: true });
await cp(nm('pdfjs-dist', 'standard_fonts'), out('pdfjs', 'standard_fonts'), { recursive: true });

// zxing-wasm reader
await mkdir(out('zxing'), { recursive: true });
await cp(nm('zxing-wasm', 'dist', 'reader', 'zxing_reader.wasm'), out('zxing', 'zxing_reader.wasm'));

// tesseract.js: worker, LSTM-only core variants (the code picks one by CPU features), English data
await mkdir(out('tesseract', 'core'), { recursive: true });
await mkdir(out('tesseract', 'lang'), { recursive: true });
await cp(nm('tesseract.js', 'dist', 'worker.min.js'), out('tesseract', 'worker.min.js'));
for (const f of await readdir(nm('tesseract.js-core'))) {
  if (/-lstm\.wasm\.js$/.test(f)) await cp(nm('tesseract.js-core', f), out('tesseract', 'core', f));
}
await cp(
  nm('@tesseract.js-data', 'eng', '4.0.0_best_int', 'eng.traineddata.gz'),
  out('tesseract', 'lang', 'eng.traineddata.gz'),
);

console.log('vendor assets copied to public/vendor');
